-- exmd16-4.hs: extended Minsky doubling (value x16, 4 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 16^4 = 65536.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x16
exmd (x, 0,    2) = exmd (  x,   0,   19)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
