exmd (x, y,   34) = exmd (  x, y+1,   35)
exmd (x, y,   35) = exmd (  x, y+1,   19)

-- Cycle 2 (pc=36): y -> x, x16
exmd (x, 0,   36) = exmd (  x,   0,   53)
exmd (x, y,   36) = exmd (  x, y-1,   37)
exmd (x, y,   37) = exmd (x+1,   y,   38)
